import { sql } from 'drizzle-orm';
import { boolean, check, foreignKey, index, integer, jsonb, pgTable, text, timestamp, unique, uniqueIndex, uuid } from 'drizzle-orm/pg-core';
import { primaryId, timestamps } from './columns.js';
import { activities } from './content.js';
import { courses, enrollments } from './courses.js';
import { gradeSourceEnum, gradingPolicyStatusEnum } from './enums.js';
import { quizAttempts } from './quizzes.js';
import { users } from './users.js';

/** One points-based rubric criterion. Ids are generated by the server. */
export type RubricCriterion = { id: string; title: string; description: string | null; maxPoints: number };

/** What a student sees after release: a copy of the grade at release time. Never contains answer keys. */
export type ReleasedGradeDetail = {
  feedback: string | null;
  criteria: Array<{ criterionId: string; title: string; points: number; maxPoints: number }>;
};

/**
 * A student's single, final text submission to an assignment. The approved rubric and deadline are
 * copied in, so later revisions of the assignment never change how the submission is graded. Rows are
 * immutable (trigger); the server clock sets `submitted_at` and the late-window check is enforced here.
 */
export const assignmentSubmissions = pgTable(
  'assignment_submissions',
  {
    id: primaryId(),
    activityId: uuid('activity_id')
      .notNull()
      .references(() => activities.id, { onDelete: 'restrict' }),
    courseId: uuid('course_id')
      .notNull()
      .references(() => courses.id, { onDelete: 'restrict' }),
    enrollmentId: uuid('enrollment_id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    body: text('body').notNull(),
    rubric: jsonb('rubric').$type<RubricCriterion[]>().notNull(),
    maxPoints: integer('max_points').notNull(),
    /** Approval time of the assignment version the student submitted to. */
    assignmentVersionApprovedAt: timestamp('assignment_version_approved_at', { withTimezone: true }).notNull(),
    dueAt: timestamp('due_at', { withTimezone: true }).notNull(),
    lateUntil: timestamp('late_until', { withTimezone: true }),
    isLate: boolean('is_late').notNull(),
    submittedAt: timestamp('submitted_at', { withTimezone: true }).notNull().defaultNow(),
    ...timestamps(),
  },
  (t) => [
    // One final submission per student and assignment.
    unique('assignment_submissions_activity_user_unique').on(t.activityId, t.userId),
    unique('assignment_submissions_id_activity_user_unique').on(t.id, t.activityId, t.userId),
    index('assignment_submissions_course_id_idx').on(t.courseId),
    index('assignment_submissions_user_id_idx').on(t.userId),
    foreignKey({
      name: 'assignment_submissions_enrollment_fk',
      columns: [t.enrollmentId, t.courseId, t.userId],
      foreignColumns: [enrollments.id, enrollments.courseId, enrollments.userId],
    }).onDelete('restrict'),
    check('assignment_submissions_body_check', sql`char_length(${t.body}) BETWEEN 1 AND 50000`),
    check('assignment_submissions_rubric_check', sql`jsonb_typeof(${t.rubric}) = 'array' AND jsonb_array_length(${t.rubric}) BETWEEN 1 AND 20`),
    check('assignment_submissions_max_points_check', sql`${t.maxPoints} BETWEEN 1 AND 2000`),
    check('assignment_submissions_late_until_check', sql`${t.lateUntil} IS NULL OR ${t.lateUntil} > ${t.dueAt}`),
    // Late policy: accepted until due_at, or until late_until when a late window exists; flagged when late.
    check('assignment_submissions_window_check', sql`${t.submittedAt} <= COALESCE(${t.lateUntil}, ${t.dueAt})`),
    check('assignment_submissions_is_late_check', sql`${t.isLate} = (${t.submittedAt} > ${t.dueAt})`),
  ],
);

/** Points per rubric criterion. A trigger checks the criterion and its maximum against the submission's rubric. */
export const assignmentCriterionScores = pgTable(
  'assignment_criterion_scores',
  {
    id: primaryId(),
    submissionId: uuid('submission_id')
      .notNull()
      .references(() => assignmentSubmissions.id, { onDelete: 'restrict' }),
    criterionId: uuid('criterion_id').notNull(),
    points: integer('points').notNull(),
    maxPoints: integer('max_points').notNull(),
    ...timestamps(),
  },
  (t) => [
    unique('assignment_criterion_scores_submission_criterion_unique').on(t.submissionId, t.criterionId),
    check('assignment_criterion_scores_points_check', sql`${t.points} >= 0 AND ${t.points} <= ${t.maxPoints}`),
    check('assignment_criterion_scores_max_points_check', sql`${t.maxPoints} BETWEEN 1 AND 100`),
  ],
);

/**
 * The gradebook: exactly one entry per student and graded activity (so quiz attempts are never
 * double-counted). `points` is the current server-calculated grade; the `released_*` columns are the
 * copy students see, written only by an explicit release. `revision` increases on every change, so
 * `released_revision < revision` means the grade changed after it was released.
 */
export const grades = pgTable(
  'grades',
  {
    id: primaryId(),
    courseId: uuid('course_id')
      .notNull()
      .references(() => courses.id, { onDelete: 'restrict' }),
    activityId: uuid('activity_id')
      .notNull()
      .references(() => activities.id, { onDelete: 'restrict' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    enrollmentId: uuid('enrollment_id').notNull(),
    source: gradeSourceEnum('source').notNull(),
    /** Best submitted attempt (quizzes). */
    quizAttemptId: uuid('quiz_attempt_id'),
    /** Graded submission (assignments). */
    submissionId: uuid('submission_id'),
    points: integer('points').notNull(),
    maxPoints: integer('max_points').notNull(),
    feedback: text('feedback'),
    /** Null when the server graded automatically (quizzes). */
    gradedByUserId: uuid('graded_by_user_id').references(() => users.id, { onDelete: 'restrict' }),
    gradedAt: timestamp('graded_at', { withTimezone: true }).notNull(),
    revision: integer('revision').notNull().default(1),
    releasedRevision: integer('released_revision'),
    releasedPoints: integer('released_points'),
    releasedMaxPoints: integer('released_max_points'),
    releasedDetail: jsonb('released_detail').$type<ReleasedGradeDetail>(),
    releasedAt: timestamp('released_at', { withTimezone: true }),
    releasedByUserId: uuid('released_by_user_id').references(() => users.id, { onDelete: 'restrict' }),
    /**
     * Quizzes (AP-023): the attempt whose score was released. Its own saved passing threshold decides the
     * released pass/fail status, so later changes to the quiz never alter it retroactively.
     */
    releasedQuizAttemptId: uuid('released_quiz_attempt_id'),
    ...timestamps(),
  },
  (t) => [
    unique('grades_activity_user_unique').on(t.activityId, t.userId),
    index('grades_course_id_user_id_idx').on(t.courseId, t.userId),
    foreignKey({
      name: 'grades_enrollment_fk',
      columns: [t.enrollmentId, t.courseId, t.userId],
      foreignColumns: [enrollments.id, enrollments.courseId, enrollments.userId],
    }).onDelete('restrict'),
    // The source record belongs to the same activity and student as the grade.
    foreignKey({
      name: 'grades_quiz_attempt_fk',
      columns: [t.quizAttemptId, t.activityId, t.userId],
      foreignColumns: [quizAttempts.id, quizAttempts.activityId, quizAttempts.userId],
    }).onDelete('restrict'),
    foreignKey({
      name: 'grades_released_quiz_attempt_fk',
      columns: [t.releasedQuizAttemptId, t.activityId, t.userId],
      foreignColumns: [quizAttempts.id, quizAttempts.activityId, quizAttempts.userId],
    }).onDelete('restrict'),
    check('grades_released_quiz_attempt_check', sql`${t.releasedQuizAttemptId} IS NULL OR (${t.source} = 'quiz' AND ${t.releasedRevision} IS NOT NULL)`),
    foreignKey({
      name: 'grades_submission_fk',
      columns: [t.submissionId, t.activityId, t.userId],
      foreignColumns: [assignmentSubmissions.id, assignmentSubmissions.activityId, assignmentSubmissions.userId],
    }).onDelete('restrict'),
    check(
      'grades_source_check',
      sql`(${t.source} = 'quiz' AND ${t.quizAttemptId} IS NOT NULL AND ${t.submissionId} IS NULL AND ${t.gradedByUserId} IS NULL)
        OR (${t.source} = 'assignment' AND ${t.submissionId} IS NOT NULL AND ${t.quizAttemptId} IS NULL AND ${t.gradedByUserId} IS NOT NULL)`,
    ),
    check('grades_points_check', sql`${t.maxPoints} >= 1 AND ${t.points} >= 0 AND ${t.points} <= ${t.maxPoints}`),
    check('grades_revision_check', sql`${t.revision} >= 1`),
    check(
      'grades_release_check',
      sql`(${t.releasedRevision} IS NULL AND ${t.releasedPoints} IS NULL AND ${t.releasedMaxPoints} IS NULL AND ${t.releasedDetail} IS NULL AND ${t.releasedAt} IS NULL AND ${t.releasedByUserId} IS NULL)
        OR (${t.releasedRevision} BETWEEN 1 AND ${t.revision} AND ${t.releasedMaxPoints} >= 1 AND ${t.releasedPoints} BETWEEN 0 AND ${t.releasedMaxPoints}
          AND ${t.releasedDetail} IS NOT NULL AND ${t.releasedAt} IS NOT NULL AND ${t.releasedByUserId} IS NOT NULL)`,
    ),
  ],
);

/**
 * A course's grading policy (AP-023). Without a row, or while it is a draft, the course grade is the
 * unweighted sum of points (the original calculation). When published, grade categories are weighted
 * (their weights total 100, checked by the API under this row's lock). `version` increases on every save
 * (optimistic concurrency: a save names the version it was based on).
 */
export const courseGradingPolicies = pgTable(
  'course_grading_policies',
  {
    courseId: uuid('course_id')
      .primaryKey()
      .references(() => courses.id, { onDelete: 'restrict' }),
    status: gradingPolicyStatusEnum('status').notNull(),
    version: integer('version').notNull().default(1),
    updatedByUserId: uuid('updated_by_user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    ...timestamps(),
  },
  (t) => [
    check('course_grading_policies_version_check', sql`${t.version} >= 1`),
    check('course_grading_policies_published_check', sql`(${t.status} = 'published') = (${t.publishedAt} IS NOT NULL)`),
  ],
);

/** A weighted grade category of a course policy (for example "Quizzes", 40 %). */
export const gradeCategories = pgTable(
  'grade_categories',
  {
    id: primaryId(),
    courseId: uuid('course_id')
      .notNull()
      .references(() => courseGradingPolicies.courseId, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    weightPercent: integer('weight_percent').notNull(),
    position: integer('position').notNull(),
    ...timestamps(),
  },
  (t) => [
    unique('grade_categories_id_course_unique').on(t.id, t.courseId),
    unique('grade_categories_course_position_unique').on(t.courseId, t.position),
    uniqueIndex('grade_categories_course_name_unique').on(t.courseId, sql`lower(${t.name})`),
    check('grade_categories_name_check', sql`char_length(${t.name}) BETWEEN 1 AND 80`),
    check('grade_categories_weight_check', sql`${t.weightPercent} BETWEEN 1 AND 100`),
    check('grade_categories_position_check', sql`${t.position} >= 0`),
  ],
);

/**
 * Which category a graded activity belongs to: at most one (the activity is the primary key). A trigger
 * (migration 0023) checks that the activity is a quiz or assignment of the category's course.
 */
export const gradeCategoryActivities = pgTable(
  'grade_category_activities',
  {
    activityId: uuid('activity_id')
      .primaryKey()
      .references(() => activities.id, { onDelete: 'cascade' }),
    categoryId: uuid('category_id').notNull(),
    courseId: uuid('course_id').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('grade_category_activities_category_idx').on(t.categoryId),
    foreignKey({
      name: 'grade_category_activities_category_fk',
      columns: [t.categoryId, t.courseId],
      foreignColumns: [gradeCategories.id, gradeCategories.courseId],
    }).onDelete('cascade'),
  ],
);
